test('does not break after any listed abbreviation', () => {
  for (const abbr of ['Mr', 'Mrs', 'Ms', 'Dr', 'Prof', 'St', 'Sr', 'Jr', 'vs', 'e.g', 'i.e']) {
    assert.equal(sentenceCount(`See ${abbr}. Smith today.`), 1, abbr);
  }
});

test('compares abbreviations without regard to case', () => {
  for (const abbr of ['MR', 'mr', 'DR', 'dr', 'Vs', 'VS', 'E.G', 'I.E', 'PROF']) {
    assert.equal(sentenceCount(`See ${abbr}. Smith today.`), 1, abbr);
  }
});

test('still breaks after a word that merely resembles an abbreviation', () => {
  assert.equal(sentenceCount('It was the Mrs. Then it ended. Done.'), 2);
  assert.equal(sentenceCount('He met the dream. Then left.'), 2);
});

test('does not break inside a decimal number', () => {
  assert.equal(sentenceCount('Pi is 3.14 today.'), 1);
});

test('does not break inside a dotted name', () => {
  assert.equal(sentenceCount('Visit example.com now. Or a.b.c later.'), 2);
});

